    need(files.length<MAX_FILES,'WORKSPACE_RECOVERY_FILE_LIMIT');
    const st=await lstat(path);
    need(privateInfo(st)&&!st.isSymbolicLink(),'WORKSPACE_RECOVERY_STAGED_FILE_INVALID');
    if(st.isDirectory()) {
      files.push({path:rel,kind:'directory'});
