        throw new Error('SF93_CONFIGURATION_REVISION_CONFLICT');
      if(expectedConfigHash!==undefined&&state.configHash!==expectedConfigHash)
        throw new Error('SF93_CONFIGURATION_DIGEST_CONFLICT');
