      parts.length===4&&parts[2]==='parts'&&/^[0-9]{6}\.part$/.test(parts[3])||
      parts.length===4&&parts[2]==='drafts'&&UUID.test(parts[3].replace(/\.json$/,''))&&parts[3].endsWith('.json');
