      pendingDelivery:0,exhaustedDelivery:0,exactRecipientEvents:0,
      legacyUniqueRecipientEvents:0,nativeAtomicAmount:'0',
      inboxAcceptedAtomicAmount:'0',pendingAtomicAmount:'0',exhaustedAtomicAmount:'0',
