    child.once('error', () => {
      clearTimeout(timer);
      reject(new Error('SF98_FLOCK_UNAVAILABLE_INSTALL_UTIL_LINUX'));
    });
    child.once('exit', code => {
      clearTimeout(timer);
      if (code === 0) resolvePromise(true);
      else if (code === CONFLICT) resolvePromise(false);
